def handle_json_rpc(request_str: str):
    """Обрабатывает входящие JSON-RPC запросы протокола MCP."""
    try:
        req = json.loads(request_str)
    except json.JSONDecodeError:
        return

    req_id = req.get("id")
    method = req.get("method")
    params = req.get("params", {})

    if method == "initialize":
        response = {
            "jsonrpc": "2.0",
            "id": req_id,
            "result": {
                "protocolVersion": "2024-11-05",
                "capabilities": {
                    "tools": {}
                },
                "serverInfo": {
                    "name": "git-assignment-server",
                    "version": "1.0.0"
                }
            }
        }
        sys.stdout.write(json.dumps(response) + "\n")
        sys.stdout.flush()

    elif method == "notifications/initialized":
        pass

    elif method == "tools/list":
        response = {
            "jsonrpc": "2.0",
            "id": req_id,
            "result": {
                "tools": TOOLS
            }
        }
        sys.stdout.write(json.dumps(response) + "\n")
        sys.stdout.flush()

    elif method == "tools/call":
        tool_name = params.get("name")
        arguments = params.get("arguments", {})

        result_text = ""
        if tool_name == "git_status_check":
            result_text = git_status_check()
        elif tool_name == "git_commit_and_push":
            result_text = git_commit_and_push(
                arguments.get("branch_name", "day17"),
                arguments.get("target_files", ["day17.py", "mcp_server_git.py", "README.md"]),
                arguments.get("commit_message", "")
            )
        elif tool_name == "create_branch_readme":
            result_text = create_branch_readme(
                arguments.get("day_number", "17"),
                arguments.get("topic", "Первый инструмент MCP"),
                arguments.get("learned_info", ""),
                arguments.get("branch_name", "day17"),
                arguments.get("code_link", ""),
                arguments.get("video_link", "")
            )
        elif tool_name == "format_submission_comments":
            result_text = format_submission_comments(
                arguments.get("day_number", "17"),
                arguments.get("branch_name", "day17"),
                arguments.get("code_link", ""),
                arguments.get("video_link", "")
            )
        else:
            result_text = f"Неизвестный инструмент: {tool_name}"

        response = {
            "jsonrpc": "2.0",
            "id": req_id,
            "result": {
                "content": [
                    {
                        "type": "text",
                        "text": result_text
                    }
                ]
            }
        }
        sys.stdout.write(json.dumps(response) + "\n")
        sys.stdout.flush()

def main():
    """Основной цикл чтения stdio."""
    for line in sys.stdin:
        line = line.strip()
        if line:
            handle_json_rpc(line)

if __name__ == "__main__":
    main()

class MCPClient:
    def __init__(self, server_script_path: str):
        self.server_script_path = str(Path(server_script_path).resolve())
        self.process: Optional[subprocess.Popen] = None
        self.msg_id = 1
        self._lock = threading.Lock()
        self.tools: List[Dict[str, Any]] = []
        self.server_info: Dict[str, Any] = {}
        self.is_connected = False
        self.start()

    def _send_request(self, method: str, params: Optional[Dict[str, Any]] = None) -> Optional[Dict[str, Any]]:
        if not self.process or self.process.poll() is not None:
            return {"error": "MCP сервер не запущен"}

        with self._lock:
            req_id = self.msg_id
            self.msg_id += 1

            req = {
                "jsonrpc": "2.0",
                "id": req_id,
                "method": method
            }
            if params is not None:
                req["params"] = params

            raw_req = json.dumps(req) + "\n"
            try:
                self.process.stdin.write(raw_req.encode("utf-8"))
                self.process.stdin.flush()

                raw_resp = self.process.stdout.readline().decode("utf-8")
                if not raw_resp:
                    return {"error": "Пустой ответ от MCP сервера"}
                return json.loads(raw_resp)
            except Exception as e:
                return {"error": f"Ошибка связи с MCP сервером: {e}"}

    def _send_notification(self, method: str, params: Optional[Dict[str, Any]] = None):
        if not self.process or self.process.poll() is not None:
            return
        with self._lock:
            req = {"jsonrpc": "2.0", "method": method}
            if params is not None:
                req["params"] = params
            raw_req = json.dumps(req) + "\n"
            try:
                self.process.stdin.write(raw_req.encode("utf-8"))
                self.process.stdin.flush()
            except Exception:
                pass

    def start(self):
        """Запускает процесс MCP сервера и инициализирует сессию."""
        if self.process and self.process.poll() is None:
            try:
                self.process.terminate()
                self.process.wait(timeout=1)
            except Exception:
                pass

        try:
            self.process = subprocess.Popen(
                [sys.executable, self.server_script_path],
                stdin=subprocess.PIPE,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                bufsize=0
            )

            # 1. Initialize
            init_resp = self._send_request("initialize", {
                "protocolVersion": "2024-11-05",
                "capabilities": {},
                "clientInfo": {"name": "ai-advent-client", "version": "1.0.0"}
            })

            if init_resp and "result" in init_resp:
                self.server_info = init_resp["result"].get("serverInfo", {})
                self._send_notification("notifications/initialized")
                self.is_connected = True
                self.refresh_tools()
            else:
                self.is_connected = False
                err_out = ""
                if self.process and self.process.poll() is not None and self.process.stderr:
                    err_out = self.process.stderr.read().decode("utf-8", errors="ignore")
                print(f"[MCPClient] Failed to initialize server. Response: {init_resp}. Stderr: {err_out}")
        except Exception as e:
            print(f"[MCPClient] Error starting server: {e}")
            self.is_connected = False

    def refresh_tools(self) -> List[Dict[str, Any]]:
        """Запрашивает актуальный список инструментов MCP сервера."""
        if not self.is_connected or not self.process or self.process.poll() is not None:
            self.start()

        if not self.is_connected:
            return []

        resp = self._send_request("tools/list")
        if resp and "result" in resp and "tools" in resp["result"]:
            self.tools = resp["result"]["tools"]
        return self.tools

    def call_tool(self, tool_name: str, arguments: Dict[str, Any] = None) -> str:
        """Вызывает инструмент MCP сервера и возвращает результат."""
        if not self.is_connected or not self.process or self.process.poll() is not None:
            self.start()

        if not self.is_connected:
            return "Ошибка: MCP сервер не подключен."

        resp = self._send_request("tools/call", {
            "name": tool_name,
            "arguments": arguments or {}
        })

        if not resp:
            return "Ошибка: нет ответа от MCP сервера."
        if "error" in resp:
            return f"Ошибка MCP: {resp['error']}"

        if "result" in resp and "content" in resp["result"]:
            contents = resp["result"]["content"]
            texts = [item.get("text", "") for item in contents if item.get("type") == "text"]
            return "\n".join(texts)

        return json.dumps(resp, ensure_ascii=False)

    def close(self):
        """Завершает процесс MCP сервера."""
        if self.process and self.process.poll() is None:
            self.process.terminate()
            self.process.wait(timeout=2)
            self.is_connected = False

def _load_dotenv() -> None:
    env_path = ROOT / ".env"
    if not env_path.exists():
        return
    for raw in env_path.read_text(encoding="utf-8").splitlines():
        line = raw.strip()
        if not line or line.startswith("#") or "=" not in line:
            continue
        key, value = line.split("=", 1)
        os.environ.setdefault(key.strip(), value.strip().strip('"').strip("'"))

def _http_json(url: str, timeout: float = 5) -> dict:
    request = urllib.request.Request(url, headers={"Content-Type": "application/json"})
    opener = urllib.request.build_opener(urllib.request.ProxyHandler({})) if url.startswith("http://127.0.0.1") else urllib.request.build_opener()
    try:
        with opener.open(request, timeout=timeout) as response:
            return json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as exc:
        message = exc.read().decode("utf-8", errors="replace")
        raise RuntimeError(f"HTTP {exc.code}: {message[:1200]}") from exc
    except (urllib.error.URLError, TimeoutError, OSError) as exc:
        raise RuntimeError(str(exc)) from exc

def _local_status() -> dict:
    try:
        _http_json(f"{LOCAL_LLM_BASE_URL}/health", timeout=3)
        models = _http_json(f"{LOCAL_LLM_BASE_URL}/v1/models", timeout=5).get("data", [])
        if not models:
            return {"connected": False, "error": "llama.cpp доступен, но модель не найдена."}
        model_id = models[0].get("id", "Qwen/Qwen3-4B-GGUF:Q4_K_M")
        context_window = None
        try:
            slots = _http_json(f"{LOCAL_LLM_BASE_URL}/slots", timeout=3)
            if isinstance(slots, list):
                values = [int(slot.get("n_ctx")) for slot in slots if isinstance(slot, dict) and slot.get("n_ctx")]
                context_window = min(values) if values else None
        except Exception:
            pass
        quantization_match = re.search(r"Q[2-8]_[K0-9]+(?:_[A-Z0-9]+)?", str(model_id), re.IGNORECASE)
        return {
            "connected": True,
            "model": model_id,
            "context_window": context_window,
            "quantization": quantization_match.group(0).upper() if quantization_match else "не определено по ID модели",
        }
    except Exception as exc:
        return {"connected": False, "error": f"Не удалось подключиться к llama.cpp на {LOCAL_LLM_BASE_URL}: {exc}"}

